INSERT INTO `contrats_modelecontrat` (`id`, `date_creation`, `date_modification`, `nom`, `type_contrat`, `objet`, `corps`, `clauses_standard`, `duree_mois_defaut`, `preavis_mois_defaut`, `est_actif`) VALUES ('f9a0fbc23f9a439cb7b186fd8ee47ddf', '2026-08-17 15:45:49.986759', '2026-08-17 15:45:49.986806', 'Bail Commercial CROUS-T Standard (Commercants & Prestataires)', 'BAIL_COMMERCIAL', 'Bail commercial domanial pour exploitation commerciale sur campus VCN', 'CONTRAT DE CONCESSION ET DE BAIL COMMERCIAL PORTANT SUR L''OCCUPATION D''UN LOCAL DU CAMPUS VCN
INSERT INTO `core_annonce` (`id`, `date_creation`, `date_modification`, `titre`, `contenu`, `date_publication`, `pin`, `bg`, `est_active`, `consigne_direction`, `emetteur_nom`, `statut`) VALUES ('182428dda2074cc785cb5a1e47ee3086', '2026-08-17 15:45:49.980318', '2026-08-17 15:45:49.980351', 'Appel a Candidatures Session 2026 - Attribution des Kiosques Commerciaux du Campus VCN', 'La Direction du Centre Regional des Oeuvres Universitaires Sociales de Thies (CROUS-T) informe la communaute universitaire et les prestataires exterieurs de l''ouverture officielle des candidatures pour l''attribution et l''exploitation des locaux commerciaux du Village Communautaire Numerique (VCN).
INSERT INTO `core_annonce` (`id`, `date_creation`, `date_modification`, `titre`, `contenu`, `date_publication`, `pin`, `bg`, `est_active`, `consigne_direction`, `emetteur_nom`, `statut`) VALUES ('2ef9ad6b6d3447b196051c44fdc70ded', '2026-08-17 15:45:49.982030', '2026-08-17 15:45:49.982103', 'Facilite Etudiants Entrepreneurs : Gratuite des Loyers Domaniaux pour l''annee 2025/2026', 'Conformement a la circulaire rectorale N° 2025-04/UIDT relative a l''insertion professionnelle et a l''incubation etudiante, les etudiants porteurs de projets selectionnes beneficient d''une exoneration complete de redevance locative mensuelle sur presentation d''une carte d''etudiant valide pour l''annee academique en cours.', '2026-08-17', 'pin-navy', '#e3f2fd', 1, 'Information obligatoire a notifier a l''ensemble des candidats etudiants.', 'Direction de la Vie Universitaire (DCUVE)', 'PUBLIEE');
INSERT INTO `core_annonce` (`id`, `date_creation`, `date_modification`, `titre`, `contenu`, `date_publication`, `pin`, `bg`, `est_active`, `consigne_direction`, `emetteur_nom`, `statut`) VALUES ('d33dd2c5fb2d4bd1bc4a30b90e623a6e', '2026-08-17 15:45:49.983948', '2026-08-17 15:45:49.984012', 'Campagne de Salubrite & Inspection Sanitaire Generale - Brigade d''Hygiene de Thies', 'Le Bureau QHSE du CROUS-T, en partenariat avec la Sous-brigade regionale d''Hygiene de Thies, entreprendra une mission d''inspection inopinee de toutes les cantines, dibiteries et kiosques alimentaires du campus du 20 au 25 du mois courant.
INSERT INTO `core_annonce` (`id`, `date_creation`, `date_modification`, `titre`, `contenu`, `date_publication`, `pin`, `bg`, `est_active`, `consigne_direction`, `emetteur_nom`, `statut`) VALUES ('f12a51be5ca34929a0d5f27512854faa', '2026-08-17 15:45:49.985285', '2026-08-17 15:45:49.985334', 'Generalisation du Reglement par Wave et Orange Money sans frais de guichet', 'L''Agence Comptable Principale du CROUS-T rappelle a tous les occupants titulaires de baux commerciaux que les redevances mensuelles doivent etre acquittees avant le 5 de chaque mois. Les paiements par Mobile Money via SyLOC-T generent instantanement le quitus numerique officiel faisant foi.', '2026-08-17', 'pin-slate', '#f5f5f5', 1, 'Rappel automatique a integrer aux avis d''echeance mensuels.', 'Agence Comptable Principale', 'PUBLIEE');
INSERT INTO `core_parametresysteme` (`id`, `date_creation`, `date_modification`, `cle`, `libelle`, `valeur`, `categorie`, `description`, `est_public`) VALUES ('0558de3844124a10a017d6a07231c5e0', '2026-08-17 15:45:49.976240', '2026-08-17 15:45:49.976358', 'contact_crous_t', 'Coordonnees Officielles du CROUS de Thies', '{"institution": "Centre Regional des Oeuvres Universitaires Sociales de Thies (CROUS-T)", "universite": "Universite Iba Der Thiam de Thies (UIDT)", "campus": "Campus VCN (Voie de Contournement Nord), Cite Universitaire", "ville": "Thies, Senegal", "boite_postale": "BP 77 Thies RP", "telephone_standard": "+221 33 951 12 34", "telephone_dcuve": "+221 33 951 56 78", "email_contact": "contact@crous-thies.sn", "email_dcuve": "dcuve@crous-thies.sn", "email_courrier": "courrier@crous-thies.sn", "horaires_ouverture": "Du Lundi au Vendredi de 08h00 a 17h00 (Pause de 13h30 a 14h30)"}', 'GENERAL', 'Informations de contact et localisation officielle du CROUS-T.', 1);
INSERT INTO `core_parametresysteme` (`id`, `date_creation`, `date_modification`, `cle`, `libelle`, `valeur`, `categorie`, `description`, `est_public`) VALUES ('0a67a346e170463bb1a400d277aae526', '2026-08-17 15:45:49.979131', '2026-08-17 15:45:49.979166', 'bareme_redevances_2026', 'Grille Tarifaire des Redevances Domaniales 2026 (FCFA)', '{"kiosque_etudiant_subventionne": 0, "kiosque_multiservices": 25000, "papeterie_imprimerie": 40000, "artisanat_couture_coiffure": 35000, "cantine_restauration_fastfood": 75000, "grande_cantine_centrale": 120000, "superette_alimentation": 60000, "taux_penalite_retard_pourcent": 10}', 'WORKFLOW', 'Bareme officiel approuve par la Direction du CROUS-T.', 1);
INSERT INTO `core_parametresysteme` (`id`, `date_creation`, `date_modification`, `cle`, `libelle`, `valeur`, `categorie`, `description`, `est_public`) VALUES ('452a5b00768a4a62b8dd393853989846', '2026-08-17 15:45:49.978002', '2026-08-17 15:45:49.978038', 'vitrine_presentation', 'Presentation de la plateforme SyLOC-T', '{"titre": "Systeme Digitalise de Gestion Domaniale et Commerciale du Campus VCN", "chapeau": "Le CROUS de Thies met a disposition des etudiants, entrepreneurs et prestataires une plateforme transparente et securisee pour la candidature, l''attribution et la gestion des espaces commerciaux du campus.", "avantages": ["Gratuite totale des redevances locatives pour les projets portes par des etudiants reguliers de l''UIDT.", "Paiement securise des redevances par Mobile Money (Wave, Orange Money, Free Money) sans frais de deplacement.", "Transparence integrale des attributions via la Commission d''evaluation du CROUS-T.", "Controle d''hygiene rigoureux assure en collaboration avec la Sous-brigade d''hygiene de Thies."]}', 'VITRINE', 'Contenu editorial de la vitrine d''accueil.', 1);
INSERT INTO `demandes_appelcandidature` (`id`, `date_creation`, `date_modification`, `titre`, `description`, `date_lancement`, `date_cloture`, `est_actif`, `local_id`, `publie_par_id`, `loyer_mensuel`) VALUES ('3544fa7303bc47a78c27bc3a0d1bef2d', '2026-08-17 15:46:10.588542', '2026-08-17 15:46:10.588576', 'Appel d''Offres N° 04/2026/CROUS-T : Restauration Rapide Thiossane & Chawarma (LOC-VCN-17)', 'Attribution du local restauration rapide sous reserve de prise en charge des travaux de refection du comptoir.', '2026-07-18 15:46:10.588202', '2026-08-12 15:46:10.588216', 0, '437d68170f004c48865fddebc587c286', '6860891911a34aae88a3893aafcd36d0', '60000.00');
INSERT INTO `demandes_appelcandidature` (`id`, `date_creation`, `date_modification`, `titre`, `description`, `date_lancement`, `date_cloture`, `est_actif`, `local_id`, `publie_par_id`, `loyer_mensuel`) VALUES ('49f533089ec54aa3992ac1c800ea3c10', '2026-08-17 15:46:10.578818', '2026-08-17 15:46:10.578856', 'Appel d''Offres N° 02/2026/CROUS-T : Salon Aminata Coiffure & Soins Dames (LOC-VCN-09)', 'Mise en concession du salon de coiffure et d''esthetique du Pavillon Ousmane Sembene. Priorite aux artisanes locales et etudiantes porteuses de projets capillaires traditionnels et modernes.', '2026-07-28 15:46:10.578434', '2026-08-15 15:46:10.578452', 0, '7ca87292fd8a44cc8b87818b67dcb601', '6860891911a34aae88a3893aafcd36d0', '35000.00');
