DROP TABLE IF EXISTS `auth_group`;
CREATE TABLE `auth_group` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `auth_group_permissions`;
CREATE TABLE `auth_group_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL,
  `permission_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `auth_group_permissions_group_id_permission_id_0cd325b0_uniq` (`group_id`,`permission_id`),
  KEY `auth_group_permissio_permission_id_84c5c92e_fk_auth_perm` (`permission_id`),
  CONSTRAINT `auth_group_permissio_permission_id_84c5c92e_fk_auth_perm` FOREIGN KEY (`permission_id`) REFERENCES `auth_permission` (`id`),
  CONSTRAINT `auth_group_permissions_group_id_b120cbf9_fk_auth_group_id` FOREIGN KEY (`group_id`) REFERENCES `auth_group` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `auth_permission`;
CREATE TABLE `auth_permission` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `content_type_id` int(11) NOT NULL,
  `codename` varchar(100) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `auth_permission_content_type_id_codename_01ab375a_uniq` (`content_type_id`,`codename`),
  CONSTRAINT `auth_permission_content_type_id_2f476e4b_fk_django_co` FOREIGN KEY (`content_type_id`) REFERENCES `django_content_type` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=149 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `comptes_demandeur`;
CREATE TABLE `comptes_demandeur` (
  `id` char(32) NOT NULL,
  `date_creation` datetime(6) NOT NULL,
  `date_modification` datetime(6) NOT NULL,
  `contact` varchar(50) NOT NULL,
  `est_etudiant` tinyint(1) NOT NULL,
  `matricule_etudiant` varchar(50) DEFAULT NULL,
  `score_fidelite` double NOT NULL,
  `utilisateur_id` char(32) NOT NULL,
  `carte_etudiant_date_validation` datetime(6) DEFAULT NULL,
  `carte_etudiant_fichier` varchar(100) DEFAULT NULL,
  `statut_verification_etudiant` varchar(32) NOT NULL,
  `valide_par_id` char(32) DEFAULT NULL,
  `carte_etudiant_date_soumission` datetime(6) DEFAULT NULL,
  `motif_rejet_carte` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `utilisateur_id` (`utilisateur_id`),
  KEY `comptes_demandeur_valide_par_id_92be70a7_fk_comptes_u` (`valide_par_id`),
  CONSTRAINT `comptes_demandeur_utilisateur_id_24b64573_fk_comptes_u` FOREIGN KEY (`utilisateur_id`) REFERENCES `comptes_utilisateur` (`id`),
  CONSTRAINT `comptes_demandeur_valide_par_id_92be70a7_fk_comptes_u` FOREIGN KEY (`valide_par_id`) REFERENCES `comptes_utilisateur` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `comptes_journalaudit`;
CREATE TABLE `comptes_journalaudit` (
  `id` char(32) NOT NULL,
  `date_creation` datetime(6) NOT NULL,
  `date_modification` datetime(6) NOT NULL,
  `action` varchar(255) NOT NULL,
  `cible` varchar(255) NOT NULL,
  `details` longtext NOT NULL,
  `utilisateur_id` char(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `comptes_journalaudit_utilisateur_id_7f70bed3_fk_comptes_u` (`utilisateur_id`),
  CONSTRAINT `comptes_journalaudit_utilisateur_id_7f70bed3_fk_comptes_u` FOREIGN KEY (`utilisateur_id`) REFERENCES `comptes_utilisateur` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `comptes_notification`;
CREATE TABLE `comptes_notification` (
  `id` char(32) NOT NULL,
  `date_creation` datetime(6) NOT NULL,
  `date_modification` datetime(6) NOT NULL,
  `contenu` longtext NOT NULL,
  `canal` varchar(16) NOT NULL,
  `est_lue` tinyint(1) NOT NULL,
  `destinataire_id` char(32) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `comptes_notification_destinataire_id_1936a649_fk_comptes_u` (`destinataire_id`),
  CONSTRAINT `comptes_notification_destinataire_id_1936a649_fk_comptes_u` FOREIGN KEY (`destinataire_id`) REFERENCES `comptes_utilisateur` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `comptes_utilisateur`;
CREATE TABLE `comptes_utilisateur` (
  `password` varchar(128) NOT NULL,
  `last_login` datetime(6) DEFAULT NULL,
  `is_superuser` tinyint(1) NOT NULL,
  `username` varchar(150) NOT NULL,
  `first_name` varchar(150) NOT NULL,
  `last_name` varchar(150) NOT NULL,
  `is_staff` tinyint(1) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `date_joined` datetime(6) NOT NULL,
  `id` char(32) NOT NULL,
  `email` varchar(254) NOT NULL,
  `role` varchar(32) NOT NULL,
  `delegation_active` tinyint(1) NOT NULL,
  `delegation_expiration` datetime(6) DEFAULT NULL,
  `nom_complet` varchar(255) DEFAULT NULL,
  `telephone` varchar(30) DEFAULT NULL,
  `specialite` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `comptes_utilisateur_groups`;
