DROP TABLE IF EXISTS `contrats_contrat`;
CREATE TABLE `contrats_contrat` (
  `id` char(32) NOT NULL,
  `date_creation` datetime(6) NOT NULL,
  `date_modification` datetime(6) NOT NULL,
  `date_signature` date NOT NULL,
  `date_debut` date NOT NULL,
