  `demande_id` char(32) DEFAULT NULL,
  `reference` varchar(40) NOT NULL,
  `statut` varchar(30) NOT NULL,
  `type_contrat` varchar(40) NOT NULL,
  `objet` varchar(255) NOT NULL,
  `clauses_particulieres` longtext NOT NULL,
  `texte_contrat` longtext NOT NULL,
  `modele_id` char(32) DEFAULT NULL,
  `convocation_date` datetime(6) DEFAULT NULL,
  `convocation_envoyee` tinyint(1) NOT NULL,
  `convocation_lieu` varchar(255) NOT NULL,
  `convocation_mode` varchar(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `contrats_contrat_reference_310e06b6_uniq` (`reference`),
  UNIQUE KEY `demande_id` (`demande_id`),
  KEY `contrats_contrat_demandeur_id_4fc71c77_fk_comptes_demandeur_id` (`demandeur_id`),
  KEY `contrats_contrat_local_id_12e3c315_fk_patrimoine_local_id` (`local_id`),
  KEY `contrats_contrat_signataire_crous_t_i_64986cb5_fk_comptes_u` (`signataire_crous_t_id`),
  KEY `contrats_contrat_modele_id_78bc6818_fk_contrats_modelecontrat_id` (`modele_id`),
  CONSTRAINT `contrats_contrat_demande_id_fc0a8470_fk_demandes_demande_id` FOREIGN KEY (`demande_id`) REFERENCES `demandes_demande` (`id`),
  CONSTRAINT `contrats_contrat_demandeur_id_4fc71c77_fk_comptes_demandeur_id` FOREIGN KEY (`demandeur_id`) REFERENCES `comptes_demandeur` (`id`),
  CONSTRAINT `contrats_contrat_local_id_12e3c315_fk_patrimoine_local_id` FOREIGN KEY (`local_id`) REFERENCES `patrimoine_local` (`id`),
  CONSTRAINT `contrats_contrat_modele_id_78bc6818_fk_contrats_modelecontrat_id` FOREIGN KEY (`modele_id`) REFERENCES `contrats_modelecontrat` (`id`),
  CONSTRAINT `contrats_contrat_signataire_crous_t_i_64986cb5_fk_comptes_u` FOREIGN KEY (`signataire_crous_t_id`) REFERENCES `comptes_utilisateur` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


